rows=[]
for group in groups:
    obj=bpy.data.objects['Canyon_L0_Far_%02d'%group['index']];mesh=obj.data
    expected=sum(r['verticesPerRing']*r['verticalRings']+2 for r in group['surfaces'])
    if len(mesh.vertices)!=expected:raise RuntimeError('Saved vertex count differs from authored ring layout.')
    edges=set(tuple(sorted(edge.vertices)) for edge in mesh.edges)
    offset=0
    for component,surface in enumerate(group['surfaces']):
        count=surface['verticesPerRing'];rings=surface['verticalRings'];minimum=float('inf');reversed_count=0;missing=0;witness=None
        for ring in range(rings-1):
            for column in range(count):
                ia=offset+ring*count+column;ib=ia+count
                if (ia,ib) not in edges:missing+=1
                pa=obj.matrix_world@mesh.vertices[ia].co;pb=obj.matrix_world@mesh.vertices[ib].co
                delta=pb.z-pa.z
                if delta<minimum:minimum=delta;witness={'lowerIndex':ia,'upperIndex':ib,'lowerWorld':list(pa),'upperWorld':list(pb)}
                if delta<=0:reversed_count+=1
        rows.append({'object':obj.name,'component':component,'kind':surface['kind'],'minimumVerticalEdgeDeltaMetres':minimum,
                     'nonIncreasingVerticalEdges':reversed_count,'missingExpectedConnectingEdges':missing,'minimumWitness':witness})
        offset+=count*rings+2
print('CANYON_V19_RING_AUDIT07 '+json.dumps({'source':bpy.data.filepath,'rows':rows,'sourceSaved':False,
    'scope':'Actual world-space adjacent ring edge ordering, not a complete self-intersection test.',
    'allExpectedEdgesFound':all(r['missingExpectedConnectingEdges']==0 for r in rows),
    'verticalOrderingPassed':all(r['nonIncreasingVerticalEdges']==0 for r in rows),'visualAccepted':False}))
